import{_ as s,c as a,a0 as t,o as i}from"./chunks/framework.BGabeMLJ.js";const u=JSON.parse('{"title":"v0.1.0","description":"","frontmatter":{},"headers":[],"relativePath":"versions/v0.1.0.md","filePath":"versions/v0.1.0.md"}'),n={name:"versions/v0.1.0.md"};function o(d,e,l,r,h,c){return i(),a("div",null,e[0]||(e[0]=[t(`<h1 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h1><blockquote><p>This release contains breaking changes for the <code>flame/flame-node</code> helm chart</p></blockquote><h2 id="node" tabindex="-1">Node <a class="header-anchor" href="#node" aria-label="Permalink to &quot;Node&quot;">​</a></h2><p>In an effort to ensure long-term support, we have added the ability to use the kubernetes Gateway API in addition to the Ingress API since the latter has been deprecated. This resulted in having to make a breaking change to the <code>values.yaml</code> file to support both APIs. This means that values files from prior versions are not compatible with this new helm chart. Users will have to update their <code>values.yaml</code> file in order to upgrade to <code>v0.1.0</code>.</p><h3 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h3><h4 id="removed-global-values" tabindex="-1">Removed global Values <a class="header-anchor" href="#removed-global-values" aria-label="Permalink to &quot;Removed global Values&quot;">​</a></h4><p>The <code>global</code> section at the top of the <code>flame-node</code> helm chart <code>values.yaml</code> file. This was previously used to simplify distributing the provided hostname to the chart and its sub-charts, but is no longer necessary so it was removed. Likewise, the ingress sections for both this helm chart and the sub-charts were removed.</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-global:</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-  node:</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-    ingress:</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-      enabled: false</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-      hostname:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+expose:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  type: none</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  hostname: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  tls:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    secretName: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  ingress:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    className: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    annotations: {}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    pathType: ImplementationSpecific</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  gateway:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    gatewayClassName: nginx</span></span></code></pre></div><p>In order to allow network routing, users must use the new <code>expose</code> section and for the <code>type</code>, choose one of the following:</p><ul><li>&quot;ingress&quot; (Kubernetes Ingress API)</li><li>&quot;gateway&quot; (Kubernetes Gateway API)</li><li>&quot;none&quot; (no external routing)</li></ul><p>Regardless if one chooses &quot;ingress&quot; or &quot;gateway&quot;, the hostname and tls fields will be applied to the selected API.</p><h4 id="robot-to-client" tabindex="-1">Robot to Client <a class="header-anchor" href="#robot-to-client" aria-label="Permalink to &quot;Robot to Client&quot;">​</a></h4><p>Hub keys were updated and the <code>values.yaml</code> was updated accordingly:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hub:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  auth:</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-    robotUser: &lt;Robot ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-    robotSecret: &lt;Robot Secret&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    clientID: &lt;Client ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    clientSecret: &lt;Client Secret&gt;</span></span></code></pre></div><h4 id="improving-security" tabindex="-1">Improving Security <a class="header-anchor" href="#improving-security" aria-label="Permalink to &quot;Improving Security&quot;">​</a></h4><h5 id="default-credentials" tabindex="-1">Default credentials <a class="header-anchor" href="#default-credentials" aria-label="Permalink to &quot;Default credentials&quot;">​</a></h5><p>Several default credentials were removed including keycloak and minio. Users must now specify these credentials when deploying by either providing a username/password directly in the <code>values.yaml</code> file or by using an existing secret. The keycloak user <code>flameuser</code> is no longer included by default unless explicitly enabled.</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keycloakx:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  defaultUserEnabled: false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  auth:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    adminUsername: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    adminPassword: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    existingSecret: &quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+dataStore:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  enabled: true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  minio:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   rootUser: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   rootPassword: &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+   existingSecret: &quot;&quot;</span></span></code></pre></div><h5 id="node-victorialogs-ui" tabindex="-1">Node VictoriaLogs UI <a class="header-anchor" href="#node-victorialogs-ui" aria-label="Permalink to &quot;Node VictoriaLogs UI&quot;">​</a></h5><p>VictoriaLogs is now the primary application for storing and serving logs from all node related components and services. It is enabled by default, but access to it&#39;s included UI is disabled as it is not currently secured behind user authentication. If ingress for the VictoriaLogs UI is enabled, it can be found at <code>https://&lt;node hostname&gt;/logs/select/vmui</code></p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+victorialogs:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  enabled: true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  ingress:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+    enabled: false</span></span></code></pre></div><h4 id="flame-node-data-store-to-datastore" tabindex="-1">flame-node-data-store to dataStore <a class="header-anchor" href="#flame-node-data-store-to-datastore" aria-label="Permalink to &quot;flame-node-data-store to dataStore&quot;">​</a></h4><p>To simplify referencing this subchart in the helper functions, it was given an alias of <code>dataStore</code> which should now be used instead</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- flame-node-data-store:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ dataStore:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    enabled: true</span></span></code></pre></div><h3 id="migration-guide" tabindex="-1">Migration Guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration Guide&quot;">​</a></h3><p>Adapting previous versions to the current one is very straightforward, the following table shows how values map from <code>values.yaml</code> files from previous versions (i.e. <code>&lt;0.1.0</code>) to the current stable version (<code>0.1.0</code>):</p><table tabindex="0"><thead><tr><th>Previous Value</th><th>Current Value</th><th>Comment</th></tr></thead><tbody><tr><td><code>.global.node.ingress.enabled</code> == &quot;true&quot;<br><code>.ingress.enabled</code> == &quot;true&quot;</td><td><code>.expose.type</code> == &quot;ingress&quot;</td><td>This can also be set to &quot;gateway&quot; if you are using the new Gateway API</td></tr><tr><td><code>.global.node.ingress.enabled</code> == &quot;false&quot;<br><code>.ingress.enabled</code> == &quot;false&quot;</td><td><code>.expose.type</code> == &quot;none&quot;</td><td></td></tr><tr><td><code>.global.node.ingress.hostname</code> == &quot;<a href="https://your-domain" target="_blank" rel="noreferrer">https://your-domain</a>&quot;<br><code>.ingress.hostname</code> == &quot;<a href="https://your-domain" target="_blank" rel="noreferrer">https://your-domain</a>&quot;</td><td><code>.expose.hostname</code> == &quot;<a href="https://your-domain" target="_blank" rel="noreferrer">https://your-domain</a>&quot;</td><td></td></tr><tr><td><code>.ingress.annotations</code></td><td><code>.expose.ingress.annotations</code></td><td></td></tr><tr><td><code>.ingress.className</code></td><td><code>.expose.ingress.className</code></td><td></td></tr><tr><td><code>.ingress.pathType</code></td><td><code>.expose.ingress.pathType</code></td><td></td></tr><tr><td><code>.ingress.tlsSecretName</code></td><td><code>.expose.tls.secretName</code></td><td></td></tr><tr><td><code>.hub.auth.robotUser</code></td><td><code>.hub.auth.clientID</code></td><td></td></tr><tr><td><code>.hub.auth.robotSecret</code></td><td><code>.hub.auth.clientSecret</code></td><td></td></tr><tr><td><code>.flame-node-data-store</code></td><td><code>.dataStore</code></td><td></td></tr><tr><td></td><td><code>.keycloakx.defaultUserEnabled</code></td><td>Enable if you want the <code>flameuser</code> test user created in your bundled keycloak instance</td></tr><tr><td></td><td><code>.keycloakx.auth</code></td><td>Enter your admin credentials in these fields</td></tr><tr><td></td><td><code>.dataStore.minio</code></td><td>If the dataStore is <code>enabled</code>, enter your admin credentials here</td></tr><tr><td></td><td><code>.victorialogs.ingress.enabled</code></td><td>Set to <code>true</code> if you want to access the VictoriaLogs UI</td></tr><tr><td></td><td><code>.proxy.existingSecret</code></td><td>Can now set proxy information using an existing secret</td></tr></tbody></table>`,27)]))}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
